#!/usr/bin/env bash
# Run inside the user's authenticated Alibaba Cloud Shell. No credentials are exported.
# Deploys only the reviewed, pinned login-gate commit; refuses a changed production baseline.
set -Eeuo pipefail
[[ $# == 2 ]] || { echo 'Usage: bash post-login-cloud-shell.sh <region> <instance-id>';exit 2; }
REGION=$1; INSTANCE=$2
[[ "$REGION" =~ ^[a-z0-9-]+$ && "$INSTANCE" =~ ^i-[a-z0-9]+$ ]]
command -v aliyun >/dev/null;command -v python3 >/dev/null
REMOTE=$(python3 - <<'PYPAYLOAD'
import base64,gzip,hashlib
payload=gzip.decompress(base64.b64decode('',validate=True))
assert hashlib.sha256(payload).hexdigest()=='ffbafa1072408f80a52a9cc6068f9ddd4001282b1eebffccb797639ac4619213'
assert len(base64.b64encode(payload))<=24*1024,'Cloud Assistant payload exceeds limit'
print(payload.decode(),end='')
PYPAYLOAD
)
REQUEST_ID=$(python3 -c 'import uuid;print("login-gate-"+str(uuid.uuid4()))')
result=$(aliyun ecs RunCommand --RegionId "$REGION" --InstanceId.1 "$INSTANCE" --Type RunShellScript --ContentEncoding PlainText --CommandContent "$REMOTE" --EnableParameter false --KeepCommand false --RepeatMode Once --Username root --WorkingDir /opt/ai-community --Timeout 2400 --ClientToken "$REQUEST_ID")
INVOKE_ID=$(printf '%s' "$result" | python3 -c 'import json,sys;print(json.load(sys.stdin)["InvokeId"])')
printf 'Deployment started: %s. Keep this terminal open for the result.\n' "$INVOKE_ID"
for attempt in {1..250}; do
  result=$(aliyun ecs DescribeInvocationResults --RegionId "$REGION" --InstanceId "$INSTANCE" --InvokeId "$INVOKE_ID" --ContentEncoding PlainText)
  status=$(printf '%s' "$result" | python3 -c 'import json,sys;r=json.load(sys.stdin).get("Invocation",{}).get("InvocationResults",{}).get("InvocationResult",[]);print(r[0].get("InvocationStatus","Pending") if r else "Pending")')
  case "$status" in
    Pending|Running|Scheduled) sleep 10;;
    *)
      printf '%s' "$result" | python3 -c 'import json,sys;r=json.load(sys.stdin)["Invocation"]["InvocationResults"]["InvocationResult"][0];print(r.get("Output",""));print("STATUS:",r.get("InvocationStatus"),"EXIT:",r.get("ExitCode"));sys.exit(0 if r.get("InvocationStatus")=="Success" and r.get("ExitCode")==0 else 1)'
      exit 0;;
  esac
done
printf 'Still running. Check invocation %s in ECS Cloud Assistant; do not start another release.\n' "$INVOKE_ID"
exit 1
